// result returns the outcome of Parse in the form of the Python reference.
func result(t *testing.T, data string, limits Limits, root Root) want {
	t.Helper()
	value, err := Parse([]byte(data), limits, root)
	if failure, ok := errors.AsType[*Error](err); ok {
		return want{Code: failure.Code}
	}
	if err != nil {
		t.Fatalf("Parse(%.40q) error = %v", data, err)
	}
	text, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("json.Marshal() error = %v", err)
	}
	sorted, err := canonjson.Sorted(text, true)
	if err != nil {
		t.Fatalf("canonjson.Sorted(%s) error = %v", text, err)
	}
	return want{Sorted: string(sorted)}
}

// The Python reference accepts an unpaired surrogate through the
// surrogatepass error handler of its decoder. Parse refuses it.
func TestParseRefusesAnUnpairedSurrogate(t *testing.T) {
	for _, data := range []string{
		`["\ud800"]`, `["\udc00"]`, `["\ud83d\u0041"]`, `["\ud83dx"]`, "[\"\xed\xa0\x80\"]",
		"\xff\xfe[\x00\\\x00\x00\xd8]\x00", "\xff\xfe\x00\xdc", "\xff\xfe\x00\xd8[\x00",
		"\x00\x00\xfe\xff\x00\x00\xd8\x00", "\xff\xfe[\x00]",
	} {
		if got := result(t, data, Limits{MaxBytes: 100}, Array); got.Code != Invalid {
			t.Errorf("Parse(%q) = %+v, want %s", data, got, Invalid)
		}
	}
}

func TestParseRefusesInvalidLimits(t *testing.T) {
	for _, limits := range []Limits{{MaxBytes: 0}, {MaxBytes: 10, MaxDepth: -1}} {
		if _, err := Parse([]byte("[]"), limits, Array); !errors.Is(err, ErrLimits) {
			t.Errorf("Parse(%+v) error = %v, want ErrLimits", limits, err)
		}
	}
}

func TestParseStopsAtTheDecoderDepth(t *testing.T) {
	levels := decoderDepth + 1
	for _, deep := range []string{
		strings.Repeat("[", levels) + strings.Repeat("]", levels),
		strings.Repeat(`{"a":`, levels) + "1" + strings.Repeat("}", levels),
	} {
		if got := result(t, deep, Limits{MaxBytes: len(deep)}, Array); got.Code != TooDeep {
			t.Errorf("Parse(%.10q, %d levels) = %+v, want %s", deep, levels, got, TooDeep)
		}
	}
}

func TestErrorNamesItsCode(t *testing.T) {
	if got := (&Error{Code: Invalid}).Error(); got != "ingress: invalid-json" {
		t.Errorf("Error() = %q, want %q", got, "ingress: invalid-json")
	}
}

func FuzzParseNeverPanics(f *testing.F) {
	for _, seed := range []string{`{"a": [1, 2.5, "x\u00e9"]}`, "[NaN]", "\xef\xbb\xbf[1]", `["\ud83d\ude00"]`} {
		f.Add([]byte(seed))
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		value, err := Parse(data, Limits{MaxBytes: 1 << 16, MaxDepth: 64}, Array)
		if _, ok := errors.AsType[*Error](err); err != nil && !ok {
			t.Fatalf("Parse() error = %v, want an *Error", err)
		}
		if err == nil {
			if _, ok := value.([]any); !ok {
				t.Fatalf("Parse() = %T, want []any", value)
			}
		}
	})
}
